/* Save the graphics state. */
int
gs_gsave(gs_gstate * pgs)
{
    gs_gstate *pnew = gstate_clone_for_gsave(pgs, "gs_gsave");

    if (pnew == NULL)
        return_error(gs_error_VMerror);
